/**
 * The `numbers` scenario's second session (R-demo-038): a long fan-out conversation, the kind where
 * the subagents are most of the bill. Its context document is one real session's (`fanout-data.ts`,
 * generated by scripts/media/fanout-fixture.mjs — names, paths and ids fictional, every count real),
 * so the context sheet has agent lanes, skill loads and "what every turn carries" to draw. The
 * dollars are the host's own per-record pricing from that capture, not re-typed here.
 *
 * The launcher row's spend chip is the same document folded the way the host folds it
 * (`ContextSpark`), so the tile and the sheet a tap away agree.
 */
import type { ContextSeriesDoc, ContextSpark } from "@waterplane/shared";
import { FANOUT_DOC } from "./fanout-data.ts";

const MIN = 60_000;

type Timed = { t: number };
const shift = <T extends Timed>(xs: readonly T[], end: number): T[] => xs.map((x) => ({ ...x, t: x.t + end }));
const shiftPairs = (xs: readonly (readonly [number, number])[], end: number): [number, number][] => xs.map(([t, v]) => [t + end, v]);

/** The document as the host would serve it at `now`, its log last written three minutes ago. */
export function fanoutDoc(now: number, sessionId: string): ContextSeriesDoc {
  const d = FANOUT_DOC as unknown as ContextSeriesDoc & { agentCum: [number, number][] };
  const end = now - 3 * MIN;
  return {
    ...d,
    sessionId,
    claudeSessionId: "c-garden-fan",
    updatedAt: end,
    samples: shift(d.samples, end),
    events: shift(d.events, end),
    agentCum: shiftPairs(d.agentCum, end),
    agents: d.agents?.map((a) => ({
      ...a,
      at: a.at + end,
      ...(a.endAt != null ? { endAt: a.endAt + end } : {}),
      ...(a.ctx ? { ctx: shiftPairs(a.ctx, end) } : {}),
      ...(a.skills ? { skills: shift(a.skills, end) } : {}),
    })),
    ...(d.coldStarts?.lastAt != null ? { coldStarts: { ...d.coldStarts, lastAt: d.coldStarts.lastAt + end } } : {}),
    ...(d.carried?.firstRequestAt != null ? { carried: { ...d.carried, firstRequestAt: d.carried.firstRequestAt + end } } : {}),
  } as ContextSeriesDoc;
}

/** The row's spark, off the same document. */
export function fanoutSpark(doc: ContextSeriesDoc): ContextSpark {
  const pts = doc.samples.map((s) => s.tok);
  const own = doc.cost?.total ?? 0;
  const agents = doc.agentCost?.total ?? 0;
  return {
    pts,
    marks: doc.events.map((e) => ({ at: e.t, kind: e.kind })),
    peak: Math.max(...pts),
    baseTok: pts[0],
    turns: doc.turns,
    usageTok: doc.usageTok,
    agentTok: doc.agentTok,
    costUsd: Math.round((own + agents) * 100) / 100,
    agentCostUsd: Math.round(agents * 100) / 100,
    windowTok: doc.windowTok,
    windowFrom: doc.windowFrom,
    autoCompactTok: doc.autoCompactTok,
    ...(doc.autoCompactSet?.tokens ? { autoCompactSetTok: doc.autoCompactSet.tokens } : {}),
    ...(doc.coldStarts ? { coldStarts: doc.coldStarts } : {}),
  };
}

/** Percent of the window left after the last request — the row's meter. */
export function fanoutLeft(doc: ContextSeriesDoc): number {
  const last = doc.samples.at(-1)?.tok ?? 0;
  return doc.windowTok ? Math.round(100 * (1 - last / doc.windowTok)) : 100;
}
